package io.coolbox.decisiontree;
import io.coolbox.internal.*;import com.sun.jna.ptr.DoubleByReference;
/** Numeric regression tree (Python: {@code decision_tree.DecisionTreeRegressor}). */
public final class DecisionTreeRegressor extends NativeHandle {private static final TreeNative N=TreeNative.INSTANCE;private int features;public DecisionTreeRegressor(){super(N.coolbox_tree_regressor_new(),N::coolbox_tree_regressor_free);}public DecisionTreeRegressor fit(double[][] x,double[] y,int depth){int c=Matrices.columns(x);if(y.length!=x.length)throw new IllegalArgumentException("target count differs from row count");ErrorBuffer e=new ErrorBuffer();e.check(N.coolbox_tree_regressor_fit(handle(),Matrices.flatten(x),x.length,c,y,depth,e.pointer(),e.capacity()));features=c;return this;}public double predict(double[] x){if(x.length!=features)throw new IllegalArgumentException("sample feature count must match fitted model");DoubleByReference o=new DoubleByReference();ErrorBuffer e=new ErrorBuffer();e.check(N.coolbox_tree_regressor_predict(handle(),x,x.length,o,e.pointer(),e.capacity()));return o.getValue();}}
